import{_ as n,a0 as o,w as p,s as d,I as s,x as e,a1 as a,A as l,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"終端基礎：在 Linux 中複製文件和目錄 | LCTT x X-CMD","titleTemplate":false,"description":"終端基礎：在 Linux 中複製文件和目錄 | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"終端基礎：在 Linux 中複製文件和目錄 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"終端基礎：在 Linux 中複製文件和目錄 | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230329.2 ⭐️ Linux Terminal Basics 7 Copy Files and Directories in Linux","title":"終端基礎：在 Linux 中複製文件和目錄","tag":"202307","desc":""},"relativePath":"202307/20230329.2 ⭐️ Linux Terminal Basics 7 Copy Files and Directories in Linux.md","filePath":"[post].md"}'),c={name:"202307/20230329.2 ⭐️ Linux Terminal Basics 7 Copy Files and Directories in Linux.md"};function h(u,i,g,m,k,f){const t=o("Link");return p(),d("div",null,[i[22]||(i[22]=s("h1",{id:"終端基礎-在-linux-中複製文件和目錄",tabindex:"-1"},[e("終端基礎：在 Linux 中複製文件和目錄 "),s("a",{class:"header-anchor",href:"#終端基礎-在-linux-中複製文件和目錄","aria-label":"Permalink to “終端基礎：在 Linux 中複製文件和目錄”"},"​")],-1)),i[23]||(i[23]=s("p",null,[s("img",{src:"https://img.linux.net.cn/data/attachment/album/202307/31/220802ozpf3gt9gpj2pp0f.jpg",alt:""})],-1)),i[24]||(i[24]=s("blockquote",null,[s("p",null,"在終端基礎知識系列的這一部分中，學習如何在 Linux 中使用命令列複製文件和目錄。")],-1)),i[25]||(i[25]=s("p",null,"複製文件是你經常執行的最基本但最重要的任務之一。",-1)),i[26]||(i[26]=s("p",null,[e("Linux 有一個專門的 "),s("code",null,"cp"),e(" 命令用於複製文件和目錄（文件夾）。")],-1)),i[27]||(i[27]=s("p",null,"在終端基礎知識系列的這一部分中，你將學習在終端中複製文件和文件夾。",-1)),s("blockquote",null,[i[6]||(i[6]=s("p",null,"📋 回想一下，以下是你迄今為止在本終端基礎知識系列中所學到的內容：",-1)),s("ul",null,[s("li",null,[a(t,{href:"https://itsfoss.com/change-directories/"},{default:l(()=>[...i[0]||(i[0]=[e("更改目錄",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://linux.cn/article-15595-1.html"},{default:l(()=>[...i[1]||(i[1]=[e("創建新目錄",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://itsfoss.com/list-directory-content/"},{default:l(()=>[...i[2]||(i[2]=[e("列出目錄內容",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://linux.cn/article-15643-1.html"},{default:l(()=>[...i[3]||(i[3]=[e("創建文件",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://itsfoss.com/view-file-contents/"},{default:l(()=>[...i[4]||(i[4]=[e("讀取文件",-1)])]),_:1})]),s("li",null,[a(t,{href:"https://linux.cn/article-15809-1.html"},{default:l(()=>[...i[5]||(i[5]=[e("刪除文件和目錄",-1)])]),_:1})])])]),i[28]||(i[28]=r('<p>讓我們繼續該系列的第七章。</p><h3 id="在-linux-命令列中複製文件" tabindex="-1">在 Linux 命令列中複製文件 <a class="header-anchor" href="#在-linux-命令列中複製文件" aria-label="Permalink to “在 Linux 命令列中複製文件”">​</a></h3><p>讓我向你展示一些複製文件的示例。</p><h4 id="將文件複製到另一個目錄" tabindex="-1">將文件複製到另一個目錄 <a class="header-anchor" href="#將文件複製到另一個目錄" aria-label="Permalink to “將文件複製到另一個目錄”">​</a></h4><p>要將一個文件複製到另一目錄，你所要做的就是遵循給定的命令語法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp 源文件 目標目錄</span></span></code></pre></div><p>例如，在這裏，我將名為 <code>Hello.txt</code> 的文件複製到名為 <code>Tux</code> 的目錄中：</p><p><img src="https://itsfoss.com/content/images/2023/02/copy-file-to-another-directory-in-linux-command-line.png" alt="copy file to another directory in linux command line"></p><p>正如你所看到的，文件已成功複製到 <code>Tux</code> 目錄中。</p><h4 id="複製文件但重命名" tabindex="-1">複製文件但重命名 <a class="header-anchor" href="#複製文件但重命名" aria-label="Permalink to “複製文件但重命名”">​</a></h4><p>你可以選擇在複製文件時重命名該文件。只需為“目標文件”指定一個不同的名稱即可。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp 源文件 改名的文件</span></span></code></pre></div><p>作為參考，在這裏，我將名為 <code>Hello.txt</code> 的文件複製到同一目錄，並將其重命名為 <code>Renamed_Hello.txt</code>：</p><p><img src="https://itsfoss.com/content/images/2023/02/rename-a-file-while-copying-in-a-same-directory-in-linux-terminal.png" alt="rename a file while copying in a same directory in linux terminal"></p><p>為什麼要這麼做？ 比如説，你必須編輯配置文件。一個好的做法是在編輯配置文件之前在同一位置對其進行備份。這樣，如果事情沒有按計劃進行，你可以恢復到舊配置。</p><h4 id="將多個文件複製到另一個位置" tabindex="-1">將多個文件複製到另一個位置 <a class="header-anchor" href="#將多個文件複製到另一個位置" aria-label="Permalink to “將多個文件複製到另一個位置”">​</a></h4><p>要將多個文件複製到另一個目錄，請按以下方式執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp File1 File2 File3 FileN Target_directory</span></span></code></pre></div><p>在這裏，我將多個文件複製到新位置。</p><p><img src="https://itsfoss.com/content/images/2023/02/copy-multiple-files-using-the-cp-command-in-linux.png" alt="copy multiple files using the cp command in linux"></p><blockquote><p>📋 當你複製多個文件時，僅使用 <code>cp</code> 命令無法重命名它們。</p></blockquote><h4 id="複製時處理重複文件" tabindex="-1">複製時處理重複文件 <a class="header-anchor" href="#複製時處理重複文件" aria-label="Permalink to “複製時處理重複文件”">​</a></h4><p>默認情況下，如果目標目錄中存在同名文件，<code>cp</code> 命令將覆蓋該文件。</p><p>為了避免覆蓋，你可以在 cp 命令中使用 <code>-n</code> 選項，它不會覆蓋現有文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -n 源文件 目標目錄</span></span></code></pre></div><p>例如，在這裏，我嘗試複製目標目錄中已有的兩個文件，並使用 <code>-v</code> 選項來展示該命令正在執行的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -n -v itsFOSS.txt LHB.txt LU.txt ~/Tux</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/how-not-to-override-files-while-copying-in-linux-using-the-cp-command.png" alt="how not to override files while copying in linux using the cp command"></p><h4 id="交互式複製文件" tabindex="-1">交互式複製文件 <a class="header-anchor" href="#交互式複製文件" aria-label="Permalink to “交互式複製文件”">​</a></h4><p>但是，當你想要覆蓋某些文件，而某些文件應該保持不變時該怎麼辦？</p><p>好吧，你可以使用 <code>-i</code> 選項在交互模式下使用 <code>cp</code> 命令，它每次都會詢問你是否應該覆蓋該文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -i 源文件 目標目錄</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/how-to-use-cp-command-in-interactive-mode.png" alt="how to use cp command in interactive mode"></p><blockquote><p>🖥️ 自己練習上述所有示例。你已經瞭解如何創建文件和文件夾，因此請重新創建所有內容。</p></blockquote><h3 id="在-linux-命令列中複製目錄" tabindex="-1">在 Linux 命令列中複製目錄 <a class="header-anchor" href="#在-linux-命令列中複製目錄" aria-label="Permalink to “在 Linux 命令列中複製目錄”">​</a></h3><p><code>mkdir</code> 命令用於創建新目錄，<code>rmdir</code> 命令用於刪除（空）目錄。但沒有用於複製目錄的 <code>cpdir</code> 命令。</p><p>你必須使用相同的 <code>cp</code> 命令，但使用遞歸選項 <code>-r</code> 將目錄及其所有內容複製到另一個位置：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 源目錄 目標目錄</span></span></code></pre></div><p>例如，在這裏，我將名為 <code>IF</code> 的目錄複製到 <code>LHB</code>：</p><p><img src="https://itsfoss.com/content/images/2023/02/how-to-copy-a-directory-in-linux-command-line.png" alt="how to copy a directory in linux command line"></p><p>但它複製了整個目錄。🤨</p><p>那麼，當你只想複製目錄內容而不是目錄本身時該怎麼辦？</p><p>你可以執行以下操作：</p><h4 id="僅複製目錄的內容-不是目錄" tabindex="-1">僅複製目錄的內容（不是目錄） <a class="header-anchor" href="#僅複製目錄的內容-不是目錄" aria-label="Permalink to “僅複製目錄的內容（不是目錄）”">​</a></h4><p>要僅複製目錄的內容，而不復制目錄本身，請在源目錄名稱的末尾附加 <code>/.</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 源目錄/. 目標目錄</span></span></code></pre></div><p>在這裏，我想複製名為 <code>IF</code> 的目錄的內容，其中包含以下三個文件：</p><p><img src="https://itsfoss.com/content/images/2023/02/check-the-file-contents-of-directory-using-the-tree-command.png" alt="check the file contents of directory using the tree command"></p><p>我將執行以下命令將 <code>IF</code> 目錄的文件內容複製到 <code>LHB</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r IF/. LHB</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/copy-the-file-contents-of-directory-not-a-directory-itself-in-linux-command-line.png" alt="copy the file contents of directory not a directory itself in linux command line"></p><p>你還可以在此處使用 <code>源目錄/*</code> 。</p><h4 id="複製多個目錄" tabindex="-1">複製多個目錄 <a class="header-anchor" href="#複製多個目錄" aria-label="Permalink to “複製多個目錄”">​</a></h4><p>要複製多個目錄，你必須按以下方式執行命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 目錄1 目錄2 目錄3 目錄N 目標目錄</span></span></code></pre></div><p>例如，在這裏，我將兩個名為 <code>IF</code> 和 <code>LU</code> 的目錄複製到 <code>LHB</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r IF LU ~/LHB</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/copy-multiple-directories-using-the-cp-command-in-linux-command-line.png" alt="copy multiple directories using the cp command in linux command line"></p><p>當你想要從多個目錄複製文件但不復制目錄本身時，你可以執行相同的操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cp -r 目錄1/. 目錄2/. 目錄3/. 目錄N/. 目標目錄</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2023/02/copy-files-from-multiple-directories-but-not-directories-their-self-using-the-cp-command.png" alt="copy files from multiple directories but not directories their self using the cp command"></p><blockquote><p>🖥️ 你還可以像重命名文件一樣重命名目錄。</p></blockquote><h3 id="測試你的知識" tabindex="-1">測試你的知識 <a class="header-anchor" href="#測試你的知識" aria-label="Permalink to “測試你的知識”">​</a></h3><p>現在，讓我們看看你對到目前為止所學到的知識還記得多少。</p><ul><li>創建一個名為 <code>copy_practice</code> 的目錄。</li><li>將文件 <code>/etc/services</code> 複製到這個新創建的文件夾。</li><li>在此目錄下創建一個名為 <code>secrets</code> 的文件夾，並將文件 <code>/etc/passwd</code> 和 <code>/etc/services</code> 複製到其中。</li><li>將 <code>copy_practice</code> 中的 <code>services</code> 文件複製到 <code>secrets</code> 文件夾中，但不要覆蓋它。</li><li>將 <code>secrets</code> 文件夾複製到你的主目錄。</li><li>刪除 <code>secrets</code> 和 <code>copy_practice</code> 目錄。</li></ul><p>這會給你一些練習。</p><p>到目前為止進展順利。你已經學到了很多東西。在下一章中，你將瞭解如何使用 <code>mv</code> 命令移動文件和文件夾。</p><hr>',68)),s("p",null,[i[8]||(i[8]=e("via: ",-1)),a(t,{href:"https://itsfoss.com/copy-files-directory-linux/"},{default:l(()=>[...i[7]||(i[7]=[e("https://itsfoss.com/copy-files-directory-linux/",-1)])]),_:1})]),s("p",null,[i[13]||(i[13]=e("作者：",-1)),a(t,{href:"https://itsfoss.com/author/sagar/"},{default:l(()=>[...i[9]||(i[9]=[e("Sagar Sharma",-1)])]),_:1}),i[14]||(i[14]=e(" 選題：",-1)),a(t,{href:"https://github.com/lkxed/"},{default:l(()=>[...i[10]||(i[10]=[e("lkxed",-1)])]),_:1}),i[15]||(i[15]=e(" 譯者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:l(()=>[...i[11]||(i[11]=[e("geekpi",-1)])]),_:1}),i[16]||(i[16]=e(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...i[12]||(i[12]=[e("wxy",-1)])]),_:1})]),s("p",null,[i[19]||(i[19]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...i[17]||(i[17]=[e("LCTT",-1)])]),_:1}),i[20]||(i[20]=e(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...i[18]||(i[18]=[e("Linux中國",-1)])]),_:1}),i[21]||(i[21]=e(" 榮譽推出",-1))])])}const C=n(c,[["render",h]]);export{y as __pageData,C as default};
